const sm83_op_info *sm83_decode(u8 opcode) { return &table[opcode]; }

bool sm83_terminates_block(u8 opcode) {
    u8 f = table[opcode].flags;
    return (f & (SM83_OP_FLAG_BRANCH | SM83_OP_FLAG_HALT | SM83_OP_FLAG_STOP)) != 0;
}
